def convert_attempts(apps, schema_editor):
    """Move the previous payment model's data into the ledger.

    Refuses to run while any attempt could still move money or hold stock (pending, or paid without an
    order): dropping those rows would silently lose a refund owed or leave stock reserved forever.
    """
    PaymentAttempt = apps.get_model("payments", "PaymentAttempt")
    Payment = apps.get_model("payments", "Payment")
    Transaction = apps.get_model("payments", "PaymentTransaction")
    Order = apps.get_model("orders", "Order")

    open_attempts = PaymentAttempt.objects.filter(status__in=["pending", "needs_refund"])
    if open_attempts.exists():
        refs = ", ".join(open_attempts.values_list("reference", flat=True)[:10])
        raise RuntimeError(
            "Payment attempts still pending or needing a refund (%s). Run `manage.py expire_payments`, "
            "refund the 'needs refund' ones in Razorpay, mark them failed, then migrate again." % refs
        )

    for attempt in PaymentAttempt.objects.exclude(order__isnull=True):
        refunded = bool(attempt.refund_id)
        payment = Payment.objects.create(
            order_id=attempt.order_id,
            purpose="full",
            method="online",
            amount=attempt.amount,
            currency=attempt.currency,
            status="refunded" if refunded else "captured",
            flow=attempt.flow,
            reference=attempt.reference,
            gateway_link_id=attempt.gateway_link_id,
            gateway_order_id=attempt.gateway_order_id,
            gateway_payment_id=attempt.gateway_payment_id,
            short_url=attempt.short_url,
        )
        charge = Transaction.objects.create(
            payment=payment, kind="charge", amount=attempt.amount, gateway_ref=attempt.gateway_payment_id or None
        )
        if refunded:
            Transaction.objects.create(
                payment=payment,
                kind="refund",
                amount=attempt.amount,
                gateway_ref=attempt.refund_id,
                parent=charge,
                reason="migrated from the previous payment model",
            )
            Order.objects.filter(pk=attempt.order_id).update(amount_paid=0)

    # Cash on delivery: every existing COD order owes its item price in cash on delivery.
    for order in Order.objects.filter(payment_method="cod"):
        status = {"delivered": "collected", "cancelled": "cancelled"}.get(order.status, "pending")
        payment = Payment.objects.create(
            order_id=order.pk, purpose="cod_balance", method="cash", amount=order.total, status=status
        )
        if status == "collected":
            Transaction.objects.create(payment=payment, kind="charge", amount=order.total, reason="cash collected")
            Order.objects.filter(pk=order.pk).update(amount_paid=order.total, payment_status="paid")

    # Postgres refuses to alter a table that still has deferred foreign-key checks pending from the
    # updates above, so run them now (and go back to the default deferred mode).
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")
    schema_editor.execute("SET CONSTRAINTS ALL DEFERRED")


